/// The custodian peg opening is kept as an OPAQUE blake3-keystream-sealed blob (never an observable value field),
/// so no reserve/circulating value ever sits readable in node state. RAM-only working state (the blob is
/// `#[serde(skip)]`); the fixed-domain keystream makes it an opaque blob today — a durable per-node-secret seal is
/// the persistence follow-on.
///
/// Layout: `r_val(16 LE) ‖ r_blind(DIGEST_LANES × 8 LE) ‖ m_val(16 LE) ‖ m_blind(DIGEST_LANES × 8 LE)`.
///
/// ⛔⛔⛔ EVERY OFFSET BELOW IS DERIVED, AND IT WAS NOT. The buffer was a literal `[0u8; 96]` with the blind
/// slices written out as `16 + i*8` and `64 + i*8` — correct at four lanes, and at eight a hard panic:
/// *"range end index 104 out of range for slice of length 96"*. This is the same class §AG turned up all
/// through the decider (stale hand-computed column offsets), and it is worth the repetition: ⭐ **a layout
/// written as a literal is a layout that cannot move.** The seal is `#[serde(skip)]` RAM-only working state,
/// so widening it breaks no wire or disk contract.
const OPENING_SEAL_DOMAIN: &[u8] = b"USDMD-CUSTODIAN-OPENING-SEAL-v1";

/// One blind, as raw lanes. ⛔ NOT `digest_to_bytes`: a blind is any 8 u64s (a domain tag, a derived value),
/// not necessarily a canonical 31-bit-per-lane digest, so the injective byte form would refuse half of them.
const OPENING_BLIND_BYTES: usize = usdm_decider::poseidon2_compress::DIGEST_LANES * 8;
/// `r_val ‖ r_blind ‖ m_val ‖ m_blind`.
const OPENING_SEAL_BYTES: usize = 2 * (16 + OPENING_BLIND_BYTES);
/// Where the minted half starts.
const OPENING_M_VAL_AT: usize = 16 + OPENING_BLIND_BYTES;

fn opening_keystream() -> [u8; OPENING_SEAL_BYTES] {
    let mut h = blake3::Hasher::new();
    h.update(OPENING_SEAL_DOMAIN);
    let mut out = [0u8; OPENING_SEAL_BYTES];
    h.finalize_xof().fill(&mut out);
    out
}

/// Lexicographic next permutation (Knuth); `false` when `p` was the last one. Pure.
fn next_permutation(p: &mut [usize]) -> bool {
    if p.len() < 2 {
        return false;
    }
    let mut i = p.len() - 1;
    while i > 0 && p[i - 1] >= p[i] {
        i -= 1;
    }
    if i == 0 {
        return false;
    }
    let mut j = p.len() - 1;
    while p[j] <= p[i - 1] {
        j -= 1;
    }
    p.swap(i - 1, j);
    p[i..].reverse();
    true
}

/// DB-77: what a custodian hands the runtime after acting on a request — the proposal to gossip on the
/// matching attestation lane (`PegAttestReq` / `PegOutAttestReq`).
#[derive(Clone, Debug)]
pub enum PegLaneProposal {
    In(crate::peg_attest::PegInProposal),
    Out(crate::peg_attest::PegOutProposal),
}

/// LIQUIDATION §10 — the persisted pool openings: the live opening per PSM, and the closing opening per closed epoch.
/// H11 §2.5 — a receipt's epoch bridge as a custodian holds it: the four source commitments `[P₁, S₁, P₂, S₂]` from the
/// chain and this custodian's openings of the two source pairs (`first` = the receipt epoch's, `second` = the next's).
struct ReceiptBridge {
    words: [crate::spend_frontier::Digest4; 4],
    first: PoolOpening,
    second: PoolOpening,
}

/// H11 §2.5 — the blinds of a withdrawal's BRIDGED `(P, S)`: secret by construction (each source's blind is a custodian
/// secret, or the live words' blind for the identity bridge), fresh per receipt (its public nullifier), and re-derivable
/// by every custodian from its own openings — the executor proves under them and each custodian books the gain under
/// the same derivation (`book_pool_gain`).
fn pool_bridge_blinds(first: &PoolOpening, second: &PoolOpening, nullifier: &[u8; 32]) -> (crate::spend_frontier::Digest4, crate::spend_frontier::Digest4) {
    let salt = u128::from_le_bytes(nullifier[..16].fixed());
    (
        op_advance_blind(b"USDMD-POOL-BRIDGE-P-v1", &first.p_blind, &second.p_blind, salt),
        op_advance_blind(b"USDMD-POOL-BRIDGE-S-v1", &first.s_blind, &second.s_blind, salt),
    )
}

type PoolOpeningsFile = (Vec<(u32, PoolOpening)>, Vec<((u32, u64), PoolOpening)>);

/// LIQUIDATION §10 — a custodian's opening of one PSM's pool words.
#[derive(Clone, Copy, Debug, PartialEq, Eq, serde::Serialize, serde::Deserialize)]
pub(crate) struct PoolOpening {
    pub t: u128,
    pub t_blind: crate::spend_frontier::Digest4,
    pub p: usdm_decider::confidential_solvency::U256,
    pub p_blind: crate::spend_frontier::Digest4,
    pub s: usdm_decider::confidential_solvency::U256,
    pub s_blind: crate::spend_frontier::Digest4,
}

impl PoolOpening {
    /// The opening of the genesis pool words (all public).
    pub(crate) fn genesis() -> Self {
        PoolOpening {
            t: 0,
            t_blind: crate::peg::GENESIS_POOL_T_BLIND,
            p: crate::peg::POOL_P_SCALE,
            p_blind: crate::peg::GENESIS_POOL_P_BLIND,
            s: [0; 4],
            s_blind: crate::peg::GENESIS_POOL_S_BLIND,
        }
    }
    /// The pool words this opening opens to (the epoch is the caller's).
    pub(crate) fn words(&self, epoch: u64) -> crate::peg::PoolWords {
        use usdm_decider::confidential_solvency::solvency_commit_256;
        crate::peg::PoolWords {
            t: solvency_commit_256([self.t as u64, (self.t >> 64) as u64, 0, 0], self.t_blind),
            p: solvency_commit_256(self.p, self.p_blind),
            s: solvency_commit_256(self.s, self.s_blind),
            epoch,
        }
    }
}

/// LIQUIDATION §10.2 (4) — a liquidation DUE at the chain's mark, as a custodian's opening derives it
/// ([`Node::due_liquidation`]): the header every custodian signs, and the inputs its five legs are proven from. Pure data,
/// so the seconds of proving run OFF the node lock on a worker thread ([`DueLiquidation::prove_legs`]).
#[derive(Clone, Debug)]
